// Package events is the change event service: the durable per-document change
// log together with everything written on top of it.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically in one serialized transaction, so
// cursors never repeat and no record is partially written, even under
// concurrent writers. Ordinary posts, offline replays, merges and snapshot
// restores all allocate from the same per-document contiguous cursor space.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log. A restore appends an ordinary change whose payload is a
// snapshot's state, recording its provenance so a repeated restore after a
// restart keeps the same idempotency/conflict decisions.
//
// Reads page by cursor in ascending order. The session view and the document
// view are the same read; the HTTP layer adds the session/permission checks.
// Long polling and push subscriptions are in-memory observers of commits:
// they register before the confirming read, hold no durable state, and are
// woken only after a change-bearing transaction has committed.
//
// The service owns only its own tables. The registration and permission
// layers are reached through its Gate interface, so a replay or merge never
// reaches into another service's storage.
package events

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrStoreClosing reports that the service is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrCompactedBase reports that a merge targets a base cursor below the
// document's compaction boundary: the changes it would be checked against
// have left the online log, so the conflict check cannot be completed. The
// caller maps it to 400; nothing is written.
var ErrCompactedBase = errors.New("baseCursor is below the compaction boundary")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// ExportedSnapshot is one row of an ExportSnapshots result.
type ExportedSnapshot struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// ErrVersionConflict reports that a version registration or rename cannot be
// applied: the version name is already bound to a different snapshot cursor,
// or the requested bind would move an existing name (and zero writes is the
// required outcome). The caller maps it to 409.
type ErrVersionConflict struct {
	Name string
}

func (e *ErrVersionConflict) Error() string {
	return fmt.Sprintf("snapshot version %q is bound to another cursor", e.Name)
}

// ErrVersionNotFound reports that no snapshot version of the document carries
// the requested name. The caller maps it to 404.
var ErrVersionNotFound = errors.New("snapshot version not found")

// SnapshotVersion is one row of a ListSnapshotVersions result: the version
// name together with the snapshot cursor it points at.
type SnapshotVersion struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// VersionResult reports the outcome of registering or renaming a snapshot
// version: the version name and the snapshot cursor it is bound to. An
// idempotent registration returns the same body as the first registration.
type VersionResult struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// schema is created when the service is constructed. Table and index shapes
// are unchanged from the pre-refactor layout, so data already on disk stays
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS change_boundaries (
	document_id TEXT NOT NULL PRIMARY KEY,
	boundary    INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS change_identities (
	document_id   TEXT NOT NULL,
	id            TEXT NOT NULL,
	device_id     TEXT NOT NULL,
	digest        BLOB NOT NULL,
	cursor        INTEGER NOT NULL,
	restored_from INTEGER,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS snapshot_versions (
	document_id TEXT NOT NULL,
	name        TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	PRIMARY KEY (document_id, name)
);
`

// Package authz is the permission service: the durable, per-document and
// per-device authorization ledger together with the system's single revoke
// verdict.
//
// Every (document, device) pair starts authorized; a grant or revoke is
// recorded per pair. The lookup and the write run in one serialized
// transaction on the shared connection and commit to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
//
// The other services do not read the permission table. They take their
// registration-and-authorization verdict through AuthorizedTx, evaluated
// inside their own write transaction, so a rejected request is judged before
// any document content is observed and the gate and the gated work commit as
// one judgment. Revoking never deletes changes, snapshots, sessions or CRDT
// state; it only produces the denial and, after the revoke commits, notifies
// the registered revoke sinks (the live subscription registries) so they can
// end the affected connections with the one-time, sticky 4403 close.
package authz

import (
	"database/sql"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// schema is created when the service is constructed; its shape is unchanged
// from the pre-refactor layout, so authorization rows already on disk stay
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
`

// RevokeSink observes a committed revoke. The change event service and the
// CRDT service register themselves to end the affected live subscriptions; a
// sink must not block and must be safe to call after the revoke transaction
// has committed. The permission service depends on this interface alone, so
// the dependency points from the observers toward the verdict and never back.
type RevokeSink interface {
	PermissionRevoked(documentID, deviceID string)
}

// Service is the permission service.
type Service struct {
	db *sql.DB

	mu    sync.Mutex
	sinks []RevokeSink
}

// New constructs the permission service over the shared kernel handle and
// creates its table.
func New(kernel *store.Store) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{db: db}, nil
}

// AddRevokeSink registers an observer notified after every committed revoke.
// It is called by the composition root while wiring the services, before the
// surface serves requests.
func (s *Service) AddRevokeSink(sink RevokeSink) {
	s.mu.Lock()
	s.sinks = append(s.sinks, sink)
	s.mu.Unlock()
}

// AuthorizedTx is the shared gate: it returns nil when deviceID is registered
// and currently authorized for documentID, store.ErrDeviceNotFound when the
// device is not registered and store.ErrPermissionDenied when its access has
// been revoked. It runs inside the caller's transaction q, so the verdict is
// taken on the same serialized connection as the work it guards, before any
// document content is read.
func (s *Service) AuthorizedTx(q store.DBTX, documentID, deviceID string) error {
	exists, err := store.DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return store.ErrDeviceNotFound
	}
	var stored int
	err = q.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
		return nil
	case err != nil:
		return err
	default:
		if stored == 0 {
			return store.ErrPermissionDenied
		}
		return nil
	}
}

// DeviceAuthorizedTx adapts the shared gate to the change event and CRDT
// services' Gate interface (which names *sql.Tx). The verdict is identical.
func (s *Service) DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error {
	return s.AuthorizedTx(tx, documentID, deviceID)
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields store.ErrDeviceNotFound and nothing is written. The lookup and the
// write run in one serialized transaction, so concurrent grant/revoke calls
// each commit completely and the final state matches the last committed
// action. After a revoke commits, every registered sink is notified; a grant
// notifies nothing (a prior revoke already ended the connection stickily).
func (s *Service) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, store.ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}

	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.mu.Lock()
		sinks := append([]RevokeSink(nil), s.sinks...)
		s.mu.Unlock()
		for _, sink := range sinks {
			sink.PermissionRevoked(documentID, deviceID)
		}
	}
	return true, nil
}

// DeleteDevicePermissionsTx removes every document-permission ledger row that
// names deviceID, inside the caller's transaction: grants and revokes the
// deregistered device held on documents vanish together with the device. It is
// the permission service's share of device deregistration, run in the same
// serialized transaction as the registration layer's cascade, so the row
// removals and the device deletion commit as one judgment. After the device
// row is gone the default verdict would be "unregistered" anyway; clearing the
// rows guarantees a device that later re-registers the same id starts with no
// inherited authorization state.
func (s *Service) DeleteDevicePermissionsTx(q store.DBTX, deviceID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE device_id = ?`, deviceID,
	)
	return err
}

// DocumentHasRowsTx reports whether the ledger holds any row (a grant or a
// revoke deviation) for documentID. It is part of document existence: a
// document whose only durable trace is a permission deviation still exists and
// can be deleted so that the same id is later a brand-new document with no
// inherited authorization state.
func (s *Service) DocumentHasRowsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM document_permissions WHERE document_id = ?)`,
		documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentPermissionsTx removes every permission-ledger row that names
// documentID, inside the caller's transaction: the per-device grant/revoke
// deviations of a deleted document vanish with it, so when the same id is
// created again every pair starts from the default (authorized) with no
// inherited ledger state. It is the permission service's share of document
// deletion, run in the same serialized transaction as the change-event and
// CRDT cascades, so the row removals and the document deletion commit as one
// judgment.
func (s *Service) DeleteDocumentPermissionsTx(q store.DBTX, documentID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE document_id = ?`, documentID,
	)
	return err
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// PermissionEntry is one row of a document's permission ledger: a currently
// registered device id together with its authorization for the document.
type PermissionEntry struct {
	DeviceID   string
	Authorized bool
}

// ListDocumentPermissions is the read-only ledger view of one document: one
// entry per currently registered device, in ascending lexicographic device-id
// order, paged by limit/offset against that same order.
//
// A device with no ledger row starts authorized, so its entry reports
// Authorized=true; a device whose latest committed action was a revoke reports
// false. Deregistered devices carry no device row and their ledger rows were
// removed by the deregistration cascade, so they never appear. An unknown
// document is indistinguishable from one on which every device keeps the
// default: every registered device lists authorized. The read runs in one
// serialized transaction, creates no row, moves no cursor and notifies no sink.
func (s *Service) ListDocumentPermissions(documentID string, limit, offset int64) ([]PermissionEntry, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	rows, err := tx.Query(
		`SELECT d.id, COALESCE(p.authorized, 1) AS authorized
		 FROM devices d
		 LEFT JOIN document_permissions p
		   ON p.document_id = ? AND p.device_id = d.id
		 ORDER BY d.id ASC
		 LIMIT ? OFFSET ?`,
		documentID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	entries := make([]PermissionEntry, 0)
	for rows.Next() {
		var entry PermissionEntry
		var stored int
		if err := rows.Scan(&entry.DeviceID, &stored); err != nil {
			return nil, err
		}
		entry.Authorized = stored != 0
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return entries, tx.Commit()
}

// The change-log status read is the change event service's read-only answer
// to "how much of this document's change log is still left to catch up on":
// the number of changes still in the online log, the greatest cursor that has
// a saved snapshot (the compaction boundary), the greatest cursor among the
// online rows, and the number of ids compaction moved out of the online log.
// Like every other read it sees only durable rows; the retained summaries in
// change_identities are counted solely as trimmed ids and never restored. The
// read starts a transaction, writes nothing and notifies no waiter or
// subscriber.

package events

// ChangeStatus is the status summary of one document's change log:
//
//   - OnlineCount is the number of change rows still in the online log;
//   - Boundary is the greatest cursor with a saved snapshot, zero when the
//     document has none;
//   - MaxCursor is the greatest cursor among the still-online rows, zero when
//     the online log is empty;
//   - Compacted is the total number of ids compaction moved out of the online
//     log (the rows retained as canonical summaries in change_identities).
//
// Every field is zero for an unknown document: an empty status is a normal
// answer, not an error, and observing it creates neither a change nor a
// snapshot.
type ChangeStatus struct {
	OnlineCount int64
	Boundary    int64
	MaxCursor   int64
	Compacted   int64
}

// GetChangeStatus answers the read-only status summary of documentID's change
// log. The gate (registration then permission) is taken first inside one
// serialized transaction — an unregistered device yields
// store.ErrDeviceNotFound and a revoked device store.ErrPermissionDenied,
// before any change content is observed. Then the four numbers are read from
// durable rows:
//
//   - the online count and the maximum online cursor come from the rows still
//     in changes;
//   - the boundary is the greatest cursor with a saved snapshot, zero when the
//     document has no snapshot;
//   - the compacted count is the number of retained summaries in
//     change_identities — exactly the ids genuinely moved out by compaction;
//     it never decreases as changes are appended and only drops when the whole
//     document is deleted.
//
// An unknown document answers four zeros and no error: the status creates no
// change, allocates no cursor, writes no snapshot and notifies no waiter or
// subscriber, so it cannot move a cursor or wake a parked poll. The verdicts
// derive solely from durable rows and are therefore byte-stable across a
// process restart.
func (s *Service) GetChangeStatus(documentID, deviceID string) (ChangeStatus, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return ChangeStatus{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first, exactly as the other gated reads do: the device row and the
	// permission row are read before any change content is observed, so a
	// rejected status read cannot reveal content.
	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return ChangeStatus{}, err
	}

	var status ChangeStatus
	if err := tx.QueryRow(
		`SELECT COUNT(*), COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&status.OnlineCount, &status.MaxCursor); err != nil {
		return ChangeStatus{}, err
	}
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM snapshots WHERE document_id = ?`,
		documentID,
	).Scan(&status.Boundary); err != nil {
		return ChangeStatus{}, err
	}
	if err := tx.QueryRow(
		`SELECT COUNT(*) FROM change_identities WHERE document_id = ?`,
		documentID,
	).Scan(&status.Compacted); err != nil {
		return ChangeStatus{}, err
	}

	if err := tx.Commit(); err != nil {
		return ChangeStatus{}, err
	}
	return status, nil
}

