	tx, err := a.Store.DB().Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	if err := store.DeleteSessionTx(tx, deviceID, sessionID); err != nil {
		return err
	}
	if err := a.checkpoints.DeleteSessionTx(tx, sessionID); err != nil {
		return err
	}
	return tx.Commit()
}

